";s:11:\"php_version\";s:3:\"7.4\";s:13:\"mysql_version\";s:5:\"5.5.5\";s:11:\"new_bundled\";s:3:\"6.7\";s:15:\"partial_version\";s:0:\"\";s:9:\"new_files\";s:1:\"1\";}i:2;O:8:\"stdClass\":11:{s:8:\"response\";s:10:\"autoupdate\";s:8:\"download\";s:51:\"https://downloads.w.org/release/wordpress-7.0.4.zip\";s:6:\"locale\";s:5:\"en_US\";s:8:\"packages\";O:8:\"stdClass\":5:{s:4:\"full\";s:51:\"https://downloads.w.org/release/wordpress-7.0.4.zip\";s:10:\"no_content\";s:62:\"https://downloads.w.org/release/wordpress-7.0.4-no-content.zip\";s:11:\"new_bundled\";s:63:\"https://downloads.w.org/release/wordpress-7.0.4-new-bundled.zip\";s:7:\"partial\";s:61:\"https://downloads.w.org/release/wordpress-7.0.4-partial-0.zip\";s:8:\"rollback\";s:62:\"https://downloads.w.org/release/wordpress-7.0.4-rollback-0.zip\";}s:7:\"current\";s:5:\"7.0.4\";s:7:\"version\";s:5:\"7.0.4\";s:11:\"php_version\";s:3:\"7.4\";s:13:\"mysql_version\";s:5:\"5.5.5\";s:11:\"new_bundled\";s:3:\"6.7\";s:15:\"partial_version\";s:3:\"7.0\";s:9:\"new_files\";s:0:\"\";}}s:12:\"last_checked\";i:1788084993;s:15:\"version_checked\";s:3:\"7.0\";s:12:\"translations\";a:0:{}}','off'),(3135,'auto_core_update_notified','a:4:{s:4:\"type\";s:7:\"success\";s:5:\"email\";s:24:\"dev-email@wpengine.local\";s:7:\"version\";s:3:\"7.0\";s:9:\"timestamp\";i:1779349998;}','off'),(3161,'can_compress_scripts','0','on'),(3357,'cfo_main_content','a:3:{s:6:\"banner\";a:3:{s:9:\"main_text\";s:29:\"Regular Price Ticket • Ends\";s:4:\"date\";s:10:\"2026-09-15\";s:14:\"follow_up_text\";s:23:\"Save Your Seat — $295\";}s:4:\"hero\";a:6:{s:5:\"badge\";s:53:\"October 20–21, 2026 | 100% Virtual | 10AM - 4PM EST\";s:5:\"title\";s:29:\"Deploy AI in Finance Function\";s:8:\"subtitle\";s:32:\"Auditable, Compliant, Controlled\";s:11:\"description\";s:186:\"Two days of world-class sessions, live product demos, and AI-driven networking — built to help CFOs and finance teams cut through the noise and find the tools reshaping modern finance.\";s:8:\"image_id\";i:141;s:11:\"sponsor_ids\";a:5:{i:0;i:165;i:1;i:167;i:2;i:169;i:3;i:347;i:4;i:393;}}s:3:\"faq\";a:12:{i:0;a:2:{s:8:\"question\";s:36:\"When does the conference take place?\";s:6:\"answer\";s:86:\"October 20-21, 2026, from 10:00 AM to 4:00 PM EST or 4:00 PM to 10:00 PM CET each day.\";}i:1;a:2:{s:8:\"question\";s:22:\"Is this fully virtual?\";s:6:\"answer\";s:132:\"Yes — 100% virtual, hosted on a dedicated event platform. You will receive your access link 48 hours before the conference starts.\";}i:2;a:2:{s:8:\"question\";s:31:\"How do I access the conference?\";s:6:\"answer\";s:277:\"All registered attendees receive a unique access link with login instructions in the days before the event, plus reminders leading up to the start. Our support team is on standby throughout the event to help with any technical issues, you will never be left without assistance.\";}i:3;a:2:{s:8:\"question\";s:55:\"Can my company purchase tickets on behalf of attendees?\";s:6:\"answer\";s:103:\"Yes. You can register and pay for colleagues using a single payment method (corporate card or invoice).\";}i:4;a:2:{s:8:\"question\";s:27:\"Who is this conference for?\";s:6:\"answer\";s:188:\"Senior finance leaders — CFOs, VPs of Finance, Finance Directors, and Controllers — at mid-market and enterprise companies actively evaluating or implementing AI in finance operations.\";}i:5;a:2:{s:8:\"question\";s:39:\"What exactly is included in the ticket?\";s:6:\"answer\";s:439:\"- Live access to all 35+ speaker sessions in two days\r\n- Access to the 7 different stages like FP&A, Accounting, Treasury, Automations and others. \r\n- 1:1 meetings with other participants, knowledge partners and vendors\r\n- Testing different tools on expo with vendor representatives\r\n- Demo of any produce exhibited on the expo stage\r\n- Certificate of attendance if requested\r\n- Claude for finance - lastly updated e-book\r\n- And much more.\";}i:6;a:2:{s:8:\"question\";s:45:\"How is this different from other conferences?\";s:6:\"answer\";s:224:\"Most AI (or Finance) events are built for engineers or product teams. This is the only conference designed specifically for finance leaders, covering deployment, governance, audit-readiness, and ROI from the CFO perspective.\";}i:7;a:2:{s:8:\"question\";s:48:\"Will I be able to ask questions during sessions?\";s:6:\"answer\";s:431:\"Yes, most sessions include a live Q&A segment, and we work with all speakers to incorporate one wherever possible. Throughout the event, our team of consultants is active in the live feed answering your questions in real time. In addition, vendor experts organized by category are available with their teams, so whatever your question — strategic, technical, or implementation-related, you will get answers from the right people.\";}i:8;a:2:{s:8:\"question\";s:34:\"Is my data secure when I register?\";s:6:\"answer\";s:152:\"Yes. We use Stripe for payment processing (PCI-DSS Level 1 compliant) and never store your card details. Personal data is handled per GDPR requirements.\";}i:9;a:2:{s:8:\"question\";s:44:\"Will my information be shared with sponsors?\";s:6:\"answer\";s:138:\"Sponsors of the event receive an attendee list with company name, role, work email. You can opt out of sponsor communications at any time.\";}i:10;a:2:{s:8:\"question\";s:32:\"Why do you require a work email?\";s:6:\"answer\";s:497:\"This is a B2B event for finance professionals at companies, your work email confirms you are part of the audience this conference is designed for, which keeps the community focused and the discussions relevant. Your registration stays with you — even if you change companies, just let us know your new work email and we will update your access. If you are an independent consultant and don’t have company email, email us at support@cfoainexus.com and we will review your registration manually.\";}i:11;a:2:{s:8:\"question\";s:22:\"How can I contact you?\";s:6:\"answer\";s:42:\"You can email us at support@cfoainexus.com\";}}}','auto'),(3363,'using_application_passwords','1','off'),(5569,'cfo_promo_modal_title','Reserve Your Free Seat','auto'),(5570,'cfo_promo_modal_subtext','Seats are limited. Once all seats are filled, access cannot be guaranteed. By registering, you agree to receive newsletters from us and collaborated party. You can unsubscribe at any time.','auto'),(18495,'_site_transient_timeout_browser_6967ec7261b3cbe6a91d798c6b951c60','1788258390','off'),(18496,'_site_transient_browser_6967ec7261b3cbe6a91d798c6b951c60','a:10:{s:4:\"name\";s:6:\"Chrome\";s:7:\"version\";s:9:\"151.0.0.0\";s:8:\"platform\";s:7:\"Windows\";s:10:\"update_url\";s:29:\"https://www.google.com/chrome\";s:7:\"img_src\";s:43:\"http://s.w.org/images/browsers/chrome.png?1\";s:11:\"img_src_ssl\";s:44:\"https://s.w.org/images/browsers/chrome.png?1\";s:15:\"current_version\";s:2:\"18\";s:7:\"upgrade\";b:0;s:8:\"insecure\";b:0;s:6:\"mobile\";b:0;}','off'),(18567,'_site_transient_timeout_browser_7c73ef5b8d3235ae0606f2e84e457ff5','1788295208','off'),(18568,'_site_transient_browser_7c73ef5b8d3235ae0606f2e84e457ff5','a:10:{s:4:\"name\";s:6:\"Chrome\";s:7:\"version\";s:9:\"145.0.0.0\";s:8:\"platform\";s:7:\"Windows\";s:10:\"update_url\";s:29:\"https://www.google.com/chrome\";s:7:\"img_src\";s:43:\"http://s.w.org/images/browsers/chrome.png?1\";s:11:\"img_src_ssl\";s:44:\"https://s.w.org/images/browsers/chrome.png?1\";s:15:\"current_version\";s:2:\"18\";s:7:\"upgrade\";b:0;s:8:\"insecure\";b:0;s:6:\"mobile\";b:0;}','off'),(18569,'_site_transient_timeout_browser_02379953b93cd223243db09f1dd4e5b9','1788295209','off'),(18570,'_site_transient_browser_02379953b93cd223243db09f1dd4e5b9','a:10:{s:4:\"name\";s:6:\"Chrome\";s:7:\"version\";s:9:\"146.0.0.0\";s:8:\"platform\";s:9:\"Macintosh\";s:10:\"update_url\";s:29:\"https://www.google.com/chrome\";s:7:\"img_src\";s:43:\"http://s.w.org/images/browsers/chrome.png?1\";s:11:\"img_src_ssl\";s:44:\"https://s.w.org/images/browsers/chrome.png?1\";s:15:\"current_version\";s